package com.brainserve.onboarding.reminders.domain.model;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="scheduled_reminders",schema="client_onboarding") public class ScheduledReminder {
@Id private UUID id;@Column(name="organization_id",nullable=false)private UUID organizationId;@Column(name="reminder_policy_id",nullable=false)private UUID reminderPolicyId;@Column(name="project_id",nullable=false)private UUID projectId;@Column(name="onboarding_id",nullable=false)private UUID onboardingId;@Column(name="step_id",nullable=false)private UUID stepId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private ScheduledReminderStatus status;@Column(name="next_run_at",nullable=false)private Instant nextRunAt;@Column(name="sent_count",nullable=false)private int sentCount;@Column(name="last_sent_at")private Instant lastSentAt;@Column(name="lease_until")private Instant leaseUntil;@Column(name="suppression_reason",length=500)private String suppressionReason;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;protected ScheduledReminder(){}
public ScheduledReminder(UUID id,UUID org,UUID policyId,UUID projectId,UUID onboardingId,UUID stepId,Instant first,Instant now){this.id=id;this.organizationId=org;this.reminderPolicyId=policyId;this.projectId=projectId;this.onboardingId=onboardingId;this.stepId=stepId;this.status=ScheduledReminderStatus.ACTIVE;this.nextRunAt=first;this.createdAt=now;this.updatedAt=now;}
public void sent(Instant now,Instant next,int maximum){sentCount++;lastSentAt=now;leaseUntil=null;updatedAt=now;if(sentCount>=maximum){status=ScheduledReminderStatus.COMPLETED;suppressionReason="Maximum reminders reached";}else nextRunAt=next;}public void reactivate(Instant next,Instant now){status=ScheduledReminderStatus.ACTIVE;nextRunAt=next;leaseUntil=null;suppressionReason=null;updatedAt=now;}public void suppress(String reason,Instant now){status=ScheduledReminderStatus.SUPPRESSED;suppressionReason=reason;leaseUntil=null;updatedAt=now;}public void complete(String reason,Instant now){status=ScheduledReminderStatus.COMPLETED;suppressionReason=reason;leaseUntil=null;updatedAt=now;}
public UUID getId(){return id;}public UUID getOrganizationId(){return organizationId;}public UUID getReminderPolicyId(){return reminderPolicyId;}public UUID getProjectId(){return projectId;}public UUID getOnboardingId(){return onboardingId;}public UUID getStepId(){return stepId;}public ScheduledReminderStatus getStatus(){return status;}public Instant getNextRunAt(){return nextRunAt;}public int getSentCount(){return sentCount;}public Instant getLastSentAt(){return lastSentAt;}public String getSuppressionReason(){return suppressionReason;}public long getVersion(){return version;}
}
